/* === ESTRUCTURA PRINCIPAL === */
.molvu-double-box {
display: flex;
justify-content: center;
align-items: center;
gap: 32px;
max-width: 1300px;
margin: 0 auto 60px auto;
flex-wrap: wrap;
}

.molvu-specs-box {
flex: 1 1 500px;
border-radius: 12px;
padding: 24px;
background-color: transparent;
box-shadow: none;
}

.molvu-extras-box {
background-color: #f9f9f9;
border-radius: 16px;
box-shadow: 0 0 0 1px #e5e7eb;
padding: 32px 24px;
max-width: 750px;
margin: 0 auto 0px auto;
}

.molvu-section {
margin-bottom: 60px;
padding: 0 16px;
}

/* === TABLAS === */
.molvu-table {
width: 100%;
max-width: 750px;
margin: 0 auto;
border-collapse: collapse;
font-size: 16px;
border-radius: 0;
box-shadow: none;
}

.molvu-table td {
padding: 12px 8px;
vertical-align: top;
word-break: break-word;
white-space: normal;
}

.molvu-table td:first-child {
width: 35%;
font-weight: bold;
}

.molvu-table tr {
display: table-row;
}
/* === LISTAS === */
.molvu-ul {
list-style: none;
padding-left: 0;
margin-left: 0;
font-size: 16px;
line-height: 1.7;
max-width: 700px;
margin: 0 auto;
text-align: center;
}

.molvu-ul li {
margin-bottom: 6px;
display: block;
list-style-type: none;
}

.molvu-ul-clean {
list-style:…

